/** Real Turbofan: original integer momentum, fuel quirks, buffered pollution and three precise airflow volumes. */
public final class TurbofanEntity extends ThermalMachine implements EnergyProvider,SidedEnergyConnector,StandardFluidTransceiver,IFluidCopiable,IRORValueProvider {
 public static final long MAX_POWER=1000000;public long power;public final FluidTank tank=new FluidTank(HbmFluids.KEROSENE,24000),blood=new FluidTank(HbmFluids.BLOOD,24000),smoke=new FluidTank(HbmFluids.SMOKE,150),leaded=new FluidTank(HbmFluids.SMOKE_LEADED,150),poison=new FluidTank(HbmFluids.SMOKE_POISON,150);
 public int afterburner,output,consumption,momentum;public boolean wasOn,showBlood,tilted;public float spin,lastSpin;public static Consumer<TurbofanEntity> clientTick=e->{},clientRemoved=e->{};
 private ItemStack cachedUpgrade;private int cachedLevel;private List<NodeConnection> active=List.of();private final Map<BlockPos,PowerNode> nodes=new LinkedHashMap<>();private FluidPorts ports;private CompoundTag lastSent;private String sourceName="";
 public TurbofanEntity(BlockPos pos,BlockState state){super(TurbofanContent.ENTITY.get(),pos,state,5);}@Override public boolean isValidBlockState(BlockState state){if(!getType().isValid(state))return false;int meta=state.getValue(DummyableBlock.LEGACY_META);return meta>=12||meta>=2&&meta<=5;}
 @Override protected String title(){return "container.machineTurbofan";}@Override public void setCustomName(Component name){sourceName=name.getString();setChanged();}@Override public Component getDisplayName(){return sourceName.isEmpty()?Component.translatable(title()):Component.literal(sourceName);}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new TurbofanMenu(id,inventory,this,worldPosition);}@Override public void writeClientSideData(AbstractContainerMenu menu,net.minecraft.network.RegistryFriendlyByteBuf buf){buf.writeBlockPos(worldPosition);}
 public static Direction airflow(BlockState state){return DummyableBlock.facing(state).getClockWise();}public static List<NodeConnection> connections(BlockPos p,Direction facing){var d=facing.getClockWise();var r=d.getCounterClockWise();return List.of(point(p.relative(r),r),point(p.relative(r).relative(d,-1),r),point(p.relative(r,-1),r.getOpposite()),point(p.relative(r,-1).relative(d,-1),r.getOpposite()));}private static NodeConnection point(BlockPos origin,Direction side){return new NodeConnection(origin.relative(side),side);}
 public static AABB volume(BlockPos p,Direction d,int kind){var r=d.getClockWise();double first=kind==0?-3.5:3.5,last=kind==0?-19.5:kind==1?8.5:3.75;double x=p.getX()+.5+d.getStepX()*first-r.getStepX()*1.5,z=p.getZ()+.5+d.getStepZ()*first-r.getStepZ()*1.5,xx=p.getX()+.5+d.getStepX()*last+r.getStepX()*1.5,zz=p.getZ()+.5+d.getStepZ()*last+r.getStepZ()*1.5;return new AABB(Math.min(x,xx),p.getY(),Math.min(z,zz),Math.max(x,xx),p.getY()+3,Math.max(z,zz));}
 public static void tick(Level level,BlockPos pos,BlockState state,TurbofanEntity e){if(level instanceof ServerLevel server)e.serverTick(server);else e.tickClient();}
 private void serverTick(ServerLevel server){if(getBlockState().getValue(DummyableBlock.LEGACY_META)<12){migrateOldHorizontal(server);return;}updatePorts(server);output=0;consumption=0;var items=slots.toArray(ItemStack[]::new);tank.setType(4,items);tank.loadTank(0,1,items);for(int i=0;i<5;i++)slots.set(i,items[i]);blood.setTankType(HbmFluids.BLOOD);wasOn=false;
  var upgrade=slots.get(2);if(upgrade!=cachedUpgrade){cachedUpgrade=upgrade;cachedLevel=upgrade.getItem() instanceof AfterburnUpgradeItem a?Math.min(a.tier(),3):0;}afterburner=cachedLevel;if(BuiltInRegistries.ITEM.getKey(upgrade.getItem()).toString().equals("hbm:flame_pony"))afterburner=100;
  long burnValue=0;int amountToBurn=Math.min(1+afterburner,tank.getFill());boolean redstone=false;for(var c:connections(worldPosition,DummyableBlock.facing(getBlockState()))){if(server.hasChunkAt(c.target())&&server.hasNeighborSignal(c.target())){redstone=true;break;}}
  if(!redstone){var trait=tank.getTankType().getTrait(FluidTraits.Combustible.class);if(trait!=null&&trait.getGrade()==FluidTraits.FuelGrade.AERO)burnValue=trait.getCombustionEnergy()/1000;if(amountToBurn>0){wasOn=true;tank.setFill(tank.getFill()-amountToBurn);output=(int)(burnValue*amountToBurn*(1+Math.min(afterburner/3D,4)));power+=output;consumption=amountToBurn;if(server.getGameTime()%20==0)pollute(server,amountToBurn*5);}}
  chargeBattery();if(burnValue>0&&amountToBurn>0)airflowEffects(server);if(power>MAX_POWER)power=MAX_POWER;var state=getUpdateTag(server.registryAccess());if(!state.equals(lastSent)||server.getGameTime()%20==0){lastSent=state;sync(150);}else setChanged();
 }
 private void chargeBattery(){if(power<0){power=0;return;}var stack=slots.get(3);if(stack.getItem() instanceof CreativeBatteryItem){power=0;return;}if(stack.getItem() instanceof HbmBattery battery){long n=Math.min(Math.min(power,battery.getChargeRate(stack)),battery.getMaxCharge(stack)-battery.getCharge(stack));power-=n;battery.chargeBattery(stack,n);}}
 private void pollute(ServerLevel server,float amount){var trait=tank.getTankType().getTrait(FluidTraits.Polluting.class);if(trait==null)return;trait.burnMap().forEach((type,rate)->{var t=type==PollutionType.SOOT?smoke:type==PollutionType.HEAVYMETAL?leaded:poison;t.setFill(t.getFill()+(int)Math.ceil(rate*amount*100));if(t.getFill()>t.getMaxFill()){int overflow=t.getFill()-t.getMaxFill();t.setFill(t.getMaxFill());PollutionSystem.increment(server,worldPosition,type,overflow/100F);if(server.random.nextInt(3)==0)server.playSound(null,worldPosition,SoundEvents.LAVA_EXTINGUISH,SoundSource.BLOCKS,.1F,1.5F);}});}
 /** Same public typed gasfire payload, with the source TargetPoint still centred on the machine. */
 private void flame(ServerLevel server,double x,double y,double z,double mx,double my,double mz,float scale){var packet=new LegacyFluidEffects.Packet(true,x,y,z,mx,my,mz,scale,null);for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<22500)PacketDistributor.sendToPlayer(player,packet);}
 private void airflowEffects(ServerLevel server){var d=airflow(getBlockState());var r=d.getClockWise();int x=worldPosition.getX(),y=worldPosition.getY(),z=worldPosition.getZ();if(afterburner>0){for(int i=0;i<2;i++){double speed=2+server.random.nextDouble()*3,deviation=server.random.nextGaussian()*.2;flame(server,x+.5F-d.getStepX()*(3-i),y+1.5F,z+.5F-d.getStepZ()*(3-i),-d.getStepX()*speed+deviation,0,-d.getStepZ()*speed+deviation,8);}if(afterburner>90&&server.random.nextInt(30)==0)server.playSound(null,x+.5,y+1.5,z+.5,HbmSounds.get("block.damage"),SoundSource.BLOCKS,3,.95F+server.random.nextFloat()*.2F);if(afterburner>90){double my=.1*server.random.nextDouble();double px=x+.5F+d.getStepX()*(server.random.nextDouble()*4-2)+r.getStepX()*(server.random.nextDouble()*2-1),py=y+1F+server.random.nextDouble()*2,pz=z+.5F-d.getStepZ()*(server.random.nextDouble()*4-2)+r.getStepZ()*(server.random.nextDouble()*2-1);flame(server,px,py,pz,0,my,0,4);}}
  for(var e:server.getEntities((Entity)null,volume(worldPosition,d,0),v->true)){if(afterburner>0){e.igniteForSeconds(5);e.hurt(server.damageSources().onFire(),5);}push(e,d);}for(var e:server.getEntities((Entity)null,volume(worldPosition,d,1),v->true))push(e,d);for(var e:server.getEntities((Entity)null,volume(worldPosition,d,2),v->true)){e.hurt(HbmDamageSources.source(server,HbmDamageSources.turbofan),1000);stick(e);if(!e.isAlive()&&e instanceof LivingEntity){DeathParticlePacket.giblets(e,0,5);server.playSound(null,e.getX(),e.getY(),e.getZ(),SoundEvents.ZOMBIE_BREAK_WOODEN_DOOR,SoundSource.BLOCKS,2,.95F+server.random.nextFloat()*.2F);blood.setFill(Math.min(blood.getMaxFill(),blood.getFill()+50));showBlood=true;}}
 }
 public static void push(Entity e,Direction d){e.setDeltaMovement(e.getDeltaMovement().add(-d.getStepX()*.2,0,-d.getStepZ()*.2));}public static void stick(Entity e){e.makeStuckInBlock(Blocks.COBWEB.defaultBlockState(),new Vec3(.25,.05,.25));}
 private void tickClient(){lastSpin=spin;if(wasOn){if(momentum<100)momentum++;}else if(momentum>0)momentum--;spin+=momentum/2;if(spin>=360){spin-=360;lastSpin-=360;}clientTick.accept(this);}
 private void updatePorts(ServerLevel server){var loaded=connections(worldPosition,DummyableBlock.facing(getBlockState())).stream().filter(c->server.hasChunkAt(c.origin())&&server.getBlockState(c.origin()).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(c.origin()))).toList();if(!loaded.equals(active)||nodes.values().stream().anyMatch(PowerNode::isExpired)){disconnect();active=List.copyOf(loaded);for(var c:loaded){var node=new PowerNode(c.origin()).setConnections(c);HbmEnergy.nodespace(server).createNode(node);nodes.put(c.origin(),node);}if(!loaded.isEmpty())ports=new FluidPorts(loaded.stream().map(NodeConnection::origin).toArray(BlockPos[]::new),loaded.toArray(NodeConnection[]::new));}if(ports!=null)ports.update(server,this);for(var node:nodes.values())if(node.hasValidNet())node.addProvider(this);}
 private void disconnect(){if(level instanceof ServerLevel server){for(var node:nodes.values())if(!node.isExpired())HbmEnergy.nodespace(server).destroyNode(node);if(ports!=null)ports.remove(server);}nodes.clear();active=List.of();ports=null;}
 @Override public void setRemoved(){disconnect();if(level!=null&&level.isClientSide)clientRemoved.accept(this);super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();if(level!=null&&level.isClientSide)clientRemoved.accept(this);super.onChunkUnloaded();}
 /** Source's actual previous-horizontal-layout migration, only when an old saved core BE is loaded. */
 private void migrateOldHorizontal(ServerLevel server){var d=Direction.from3DDataValue(getBlockState().getValue(DummyableBlock.LEGACY_META));var block=(TurbofanBlock)getBlockState().getBlock();var data=saveWithFullMetadata(server.registryAccess());disconnect();server.removeBlockEntity(worldPosition);DummyableBlock.safely(()->{server.setBlock(worldPosition,block.defaultBlockState().setValue(DummyableBlock.LEGACY_META,d.get3DDataValue()+10),3);var dim=DummyableBlock.rotate(block.dimensions(),d);for(var mutable:BlockPos.betweenClosed(worldPosition.offset(-dim[4],-dim[1],-dim[2]),worldPosition.offset(dim[5],dim[0],dim[3]))){var p=mutable.immutable();if(p.equals(worldPosition))continue;var away=p.getY()>worldPosition.getY()?Direction.UP:p.getX()<worldPosition.getX()?Direction.WEST:p.getX()>worldPosition.getX()?Direction.EAST:p.getZ()<worldPosition.getZ()?Direction.NORTH:Direction.SOUTH;server.setBlock(p,block.defaultBlockState().setValue(DummyableBlock.LEGACY_META,away.get3DDataValue()),3);}});for(var c:connections(worldPosition,d))block.setPort(server,c.origin(),true);if(server.getBlockEntity(worldPosition) instanceof TurbofanEntity next)next.loadWithComponents(data,server.registryAccess());}
 @Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null;}@Override public boolean canConnect(HbmFluidType type,Direction side){return side!=null;}@Override public long getPower(){return power;}@Override public void setPower(long value){power=value;setChanged();}@Override public long getMaxPower(){return MAX_POWER;}@Override public long energyStored(){return power;}@Override public long energyCapacity(){return MAX_POWER;}
 @Override public FluidTank[] getAllTanks(){return new FluidTank[]{tank,blood,smoke,leaded,poison};}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{tank};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{blood,smoke,leaded,poison};}@Override public FluidTank getTankToPaste(){return null;}@Override public List<TankView> tanks(){return Arrays.stream(getAllTanks()).map(t->new TankView(t.getTankType(),t.getFill(),t.getMaxFill())).toList();}
 @Override public int[] getSlotsForFace(Direction side){return new int[0];}@Override public boolean canPlaceItem(int slot,ItemStack stack){return false;}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"state",PREFIX_VALUE+"output",PREFIX_VALUE+"power",PREFIX_VALUE+"fuel",PREFIX_VALUE+"blood",PREFIX_VALUE+"afterburner"};}@Override public String provideRORValue(String name){return switch(name){case PREFIX_VALUE+"state"->wasOn?"1":"0";case PREFIX_VALUE+"output"->""+output;case PREFIX_VALUE+"power"->""+power;case PREFIX_VALUE+"fuel"->""+tank.getFill();case PREFIX_VALUE+"blood"->""+blood.getFill();case PREFIX_VALUE+"afterburner"->""+afterburner;default->null;};}
 @Override protected void saveMachine(CompoundTag tag){tag.putLong("powerTime",power);tank.writeToNBT(tag,"fuel");blood.writeToNBT(tag,"blood");smoke.writeToNBT(tag,"smoke0");leaded.writeToNBT(tag,"smoke1");poison.writeToNBT(tag,"smoke2");tag.putBoolean("showBlood",showBlood);tag.putBoolean("tilted",tilted);}@Override protected void loadMachine(CompoundTag tag){power=tag.getLong("powerTime");tank.readFromNBT(tag,"fuel");blood.readFromNBT(tag,"blood");smoke.readFromNBT(tag,"smoke0");leaded.readFromNBT(tag,"smoke1");poison.readFromNBT(tag,"smoke2");showBlood=tag.getBoolean("showBlood");tilted=tag.getBoolean("tilted");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=super.getUpdateTag(lookup);tag.putByte("afterburner",(byte)afterburner);tag.putBoolean("wasOn",wasOn);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){super.handleUpdateTag(tag,lookup);afterburner=tag.getByte("afterburner");wasOn=tag.getBoolean("wasOn");}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.remove("Items");var items=new ListTag();for(int i=0;i<5;i++)if(!slots.get(i).isEmpty()){var data=(CompoundTag)slots.get(i).save(lookup);data.putByte("slot",(byte)i);items.add(data);}tag.put("items",items);if(!sourceName.isEmpty())tag.putString("name",sourceName);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);if(tag.contains("items",Tag.TAG_LIST)){slots.replaceAll(e->ItemStack.EMPTY);for(var t:tag.getList("items",Tag.TAG_COMPOUND)){var data=(CompoundTag)t;int slot=data.getByte("slot");if(slot>=0&&slot<5)slots.set(slot,ItemStack.parseOptional(lookup,data));}}sourceName=tag.getString("name");}
}
